window.HAZEL_LECTURES = [{"id":"L1","titleZh":"人體生理學導論 I","titleEn":"Introduction to Human Physiology I","blocks":[{"t":"Introduction to Human Physiology I","k":"h"},{"t":"Module Intended Learning Outcomes (MILOs):","k":"h"},{"t":"On completion of this lesson, students are expected to be able to:","k":"h"},{"t":"• Explain the structure and function of cells, tissues and organs of major body systems and physiological processes.","k":"li"},{"t":"Contents","k":"h"},{"t":"• Overview of Human Physiology","k":"li"},{"t":"• Levels of structural organization","k":"li"},{"t":"• Cell structure and Function","k":"li"},{"t":"• Levels of organization in body","k":"li"},{"t":"• Gene","k":"li"},{"t":"• Cell division and Apoptosis","k":"li"},{"t":"Learning outcomes: By the end of this lecture, students will be able to:","k":"h"},{"t":"• Describe the levels of structural organization in the human body, from chemical level to organism level.","k":"li"},{"t":"• Identify and explain the basic structure and function of a human cell, including major organelles and their roles.","k":"li"},{"t":"• Outline the levels of biological organization, showing how cells form tissues, organs, and systems.","k":"li"},{"t":"• Explain the concept of a gene, its role in heredity, and how it contributes to protein synthesis.","k":"li"},{"t":"• Describe the process of cell division and apoptosis.","k":"li"},{"t":"Anatomy and Physiology 解剖學與生理學","k":"h"},{"t":"• Anatomy - the structures結構 that make up the body and how those structures relate with each other e.g. Structure of the Heart","k":"li"},{"t":"• Macroscopic vs Microscopic anatomy","k":"li"},{"t":"• Can be seen vs cannot be seen by the naked eye","k":"li"},{"t":"• Physiology - how the body and its part work or function功能 e.g. How the heart pumps blood?","k":"li"},{"t":"Introduction 4 primary food substances are essential to maintain daily life of human","k":"p"},{"t":"1. Carbohydrates碳水化合物","k":"li"},{"t":"2. Lipids脂質","k":"li"},{"t":"3. Proteins蛋白質","k":"li"},{"t":"4. Water水","k":"li"},{"t":"1. Carbohydrates 碳水化合物/醣類/糖類","k":"li"},{"t":"• Organic food substances made up of carbon (C), hydrogen (H) & oxygen (O) atoms.","k":"li"},{"t":"• H:O ratio = 2:1","k":"li"},{"t":"• Found in rice, bread, fruit, etc.","k":"li"},{"t":"• Three classes:","k":"li"},{"t":"• Monosaccharides (simple sugars)","k":"li"},{"t":"• Disaccharides (double sugars)","k":"li"},{"t":"• Polysaccharides","k":"li"},{"t":"Three classes of Carbohydrates","k":"h"},{"t":"Class Example Made up of Characteristics","k":"h"},{"t":"• Major end-product of carbohydrate digestion Glucose (葡萄糖) -","k":"li"},{"t":"• Broken down during respiration to Monosaccharide release energy","k":"li"},{"t":"• Sweetest simple sugar Fructose (果糖) -","k":"li"},{"t":"• Commonly found in fruit and honey Maltose (麥芽糖) Glucose + Glucose • Intermediate in the digestion of starch Disaccharide Sucrose (蔗糖) Glucose + Fructose • Commonly known as table sugar Starch (澱粉) Glucose • Major food reserve in plants Glycogen (糖原) Glucose • Major carbohydrate stored in animal Polysaccharide","k":"li"},{"t":"• Makes up the cell wall of plants Cellulose (纖維素) Glucose","k":"li"},{"t":"• Indigestible by human","k":"li"},{"t":"Functions of Carbohydrates","k":"h"},{"t":"• Energy source • Structural support","k":"li"},{"t":"• Principal/Primary source of body • contribute to cell structure and energy synthesis of cell products","k":"li"},{"t":"• Energy storage • Component of DNA and RNA","k":"li"},{"t":"• Excessive glucose stored in body as • form part of the structure of DNA glycogen, which primarily stored in and RNA liver and skeletal muscles DNA (Deoxyribonucleic acid)去氧核糖核酸","k":"li"},{"t":"• When energy demands increases, RNA (Ribonucleic acid)核糖核酸 glycogen is broken down into glucose and used for energy","k":"li"},{"t":"2. Lipids 脂質","k":"li"},{"t":"• Made up of carbon, hydrogen and oxygen","k":"li"},{"t":"• Insoluble in water but dissolve readily in organic solvents (有機溶 劑) e.g. alcohol, acetone (丙酮) and ethers (乙醚)","k":"li"},{"t":"• Two types of lipids: ❑ Fats (semi-solid at room temperature) ❑ Oils (liquid at room temperature)","k":"li"},{"t":"• Triglyceride (三酸甘油酯) (3+1) ❑ Subcategory of lipid made up of 3 fatty acid molecules and 1 glycerol molecule","k":"li"},{"t":"Functions of Lipids","k":"h"},{"t":"• Food reserve and energy source • Metabolic regulators (代謝調節劑)","k":"li"},{"t":"• The fats (usually triglycerides) are • Some hormones are lipids in nature, important food reserve materials e.g. sex hormones","k":"li"},{"t":"• When carbohydrate storage is used • Water-proof layer (防水層) up, fats are often used","k":"li"},{"t":"• In mammals’ skin, sebaceous glands","k":"li"},{"t":"• Structural materials secrete oil to keep skin for","k":"li"},{"t":"• Phospholipids (磷脂) are important waterproof compounds in the cell membranes • Protection","k":"li"},{"t":"• Fat surrounding the internal organs e.g. kidney, act as shock absorbance (減震作用)","k":"li"},{"t":"3. Proteins蛋白質","k":"li"},{"t":"• Large, complex molecules, Made up of • The basic units of protein are called carbon, hydrogen, oxygen and nitrogen amino acids 胺基酸","k":"li"},{"t":"• Other elements, such as sulphur and • Amino acids join together to form a polypeptide 多肽 phosphorus, are sometimes present","k":"li"},{"t":"• Polypeptides link together to form a protein","k":"li"},{"t":"amino acids 胺基酸","k":"h"},{"t":"Functions of Proteins","k":"h"},{"t":"1. Antibody - Immune response. Defensive proteins, known as antibodies, bind to foreign invaders like bacteria and viruses to clear them from the body.","k":"li"},{"t":"2. Enzyme - Proteins like enzymes speed up chemical reactions in the body, such as breaking down food during digestion and building new molecules.","k":"li"},{"t":"3. Messenger - Hormones and receptors (such as insulin) act as chemical messengers that transmit signals to coordinate processes between different cells and organs.","k":"li"},{"t":"4. Structural components - Structural proteins like keratin and collagen provide strength, shape, and support to cells, tissues, hair, skin, and bones.","k":"li"},{"t":"5. Transport/Storage - Proteins move vital molecules where they need to go; for example, hemoglobin carries oxygen through the blood, while other proteins store nutrients like iron.","k":"li"},{"t":"Denaturation & Renaturation Denaturation蛋白質變性","k":"p"},{"t":"• The loss of the specific three-dimensional conformation of a protein molecule","k":"li"},{"t":"• Amino acid sequence of the protein remains unaffected","k":"li"},{"t":"• Effects: This leads to the loss of solubility and biological activities of the protein (e.g., cooking an egg white causes the albumin protein to coagulate irreversibly). (Top image) When cooking an egg, the protein ovalbumin in the egg white undergoes denaturation and loss of solubility.","k":"li"},{"t":"• Denatured proteins have a looser, more random (Bottom image) Paperclips provide a visual analogy to help structure; most are insoluble. conceptualize the denaturation process.","k":"li"},{"t":"Renaturation蛋白質復性","k":"h"},{"t":"• The regain of the biological activities of the protein","k":"li"},{"t":"Factors causing protein denaturation","k":"h"},{"t":"• Heat or radiation","k":"li"},{"t":"• Extreme pH","k":"li"},{"t":"• Mechanical force","k":"li"},{"t":"• Chemicals e.g. nonpolar solvents and detergents","k":"li"},{"t":"4. Water","k":"li"},{"t":"• 75% of human body is made up of water","k":"li"},{"t":"• Water is a vital substance","k":"li"},{"t":"Functions of Water Good solvent","k":"h"},{"t":"• Medium for metabolic reactions","k":"li"},{"t":"• Dilute waste substances and prevent them from harming the body","k":"li"},{"t":"Temperature regulator","k":"h"},{"t":"• Water has a high heat capacity熱容","k":"li"},{"t":"• Helps to maintain the body temperature","k":"li"},{"t":"Strong surface tension","k":"h"},{"t":"• Strong attraction between water molecules","k":"li"},{"t":"• Water rises readily by capillary action (毛細作用)","k":"li"},{"t":"Transporter","k":"h"},{"t":"• Water in the blood carries nutrients from the foods we eat to tissues throughout the body","k":"li"},{"t":"Lubricant","k":"h"},{"t":"• The synovial fluid (滑液) helps joints move easily","k":"li"},{"t":"• Water moistens food as it passes along the digestive tract, starting from saliva in the mouth and throat that makes swallowing easy, and ending with the passage of water-softened feces through the anus Adenosine triphosphate (ATP) 三磷酸腺苷","k":"li"},{"t":"• Energy-carrying molecule found in the cells of all living things","k":"li"},{"t":"• Source of energy for biological activities of the cell ATP ↔ ADP + Pi + energy","k":"li"},{"t":"• ADP (adenosine diphosphate), Pi (inorganic phosphate)","k":"li"},{"t":"• Converting ADP to ATP is a method for energy storage until it is needed","k":"li"},{"t":"• ATP hydrolysis provides the energy needed for many essential processes in organisms and cells. These include intracellular signaling, DNA and RNA synthesis, Purinergic signaling, synaptic signaling, active transport, and muscle contraction","k":"li"},{"t":"Energy and Chemical Reactions In the two reactions shown here, the larger “sunburst” represents greater potential energy and the smaller “sunburst” represents less potential energy.","k":"p"},{"t":"(a) The input of energy is required for the synthesis of ATP. (b) Energy is released as a result of the breakdown of ATP.","k":"p"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 2 p.50] Nucleic Acids 核酸","k":"p"},{"t":"• Two types of nucleic acids. Storage and expression of genomic information","k":"li"},{"t":"• Deoxyribonucleic acid (DNA) - encodes編碼 the information cells need to make proteins, acts as the genetic materials of all organisms","k":"li"},{"t":"• Ribonucleic acid (RNA) - comes in different molecular forms that play multiple cellular roles, including protein synthesis蛋白質合成.","k":"li"},{"t":"• DNA acts as the genetic materials of all organisms","k":"li"},{"t":"Transcription Translation DNA RNA Protein Mineral Salts and Ions Mineral salts and ions Functions","k":"p"},{"t":"1) Constituent of bones and teeth Calcium","k":"li"},{"t":"2) It is involved in blood clotting and muscle contraction Chlorine Maintain the balance between anion負離子 and cation正離子","k":"li"},{"t":"Phosphate Constituent of nucleic acids, ATP, bones and teeth","k":"h"},{"t":"Fluorine It is important in improving resistance to tooth decay","k":"h"},{"t":"Iodine It is the component of growth hormone and thyroxine","k":"h"},{"t":"Iron It is the constituent of many enzymes, haemoglobin and myoglobin肌紅蛋白 Cells & Tissues A Human Cell A generalized human cell showing the plasma membrane, nucleus, and cytoplasm with its organelles. Although no single cell contains all these organelles, many cells contain a large number of them.","k":"p"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 3 p.73]","k":"p"},{"t":"Cell 細胞","k":"h"},{"t":"• The basic structural and functional unit of living organisms","k":"li"},{"t":"• Can be very small (microscopic) or very large (macroscopic)","k":"li"},{"t":"• Differentiated cells are important in a multicellular organism because they are able to perform a specialized function in the body","k":"li"},{"t":"1. Cell Membrane / Plasma Membrane細胞膜","k":"li"},{"t":"• Covers the surface of every living cells, enclose the cytoplasm","k":"li"},{"t":"• Separates the material outside the cell (extracellular) from the material inside the cell (intracellular)","k":"li"},{"t":"• Composed of 2 layers of phospholipid molecules → phospholipid bilayer","k":"li"},{"t":"• Proteins scatter amongst phospholipids, functioning as receptors and transport proteins","k":"li"},{"t":"• Function:","k":"li"},{"t":"• Maintains the integrity of a cell","k":"li"},{"t":"• Controls the movement of materials into and out of the cells","k":"li"},{"t":"Plasma Membrane Fluid-mosaic model of the plasma membrane. The membrane is composed of a bilayer of phospholipids and cholesterol with proteins “floating” in the membrane. The nonpolar, hydrophobic region of each phospholipid molecule is directed toward the center of the membrane, and the polar, hydrophilic region is directed toward either the extracellular fluid or the cytoplasm.","k":"p"},{"t":"A phospholipid consists of a hydrophilic (water[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 3 p.78] loving) head and hydrophobic (water-fearing) tail","k":"p"},{"t":"2. Cytoplasm細胞質","k":"li"},{"t":"• Fluid, jellylike substance between the cell membrane and the nucleus in which organelles 細胞器 are suspended","k":"li"},{"t":"• Within the cytoplasm, materials move by diffusion","k":"li"},{"t":"• Cytosol胞質液 is the fluid part of cytoplasm","k":"li"},{"t":"• Function:","k":"li"},{"t":"• Serves as matrix substance 基質物質 for chemical reactions to occur","k":"li"},{"t":"• Provides a platform upon which other organelles can operate within the cell. All of the functions for cell expansion, growth and replication are carried out in the cytoplasm of a cell","k":"li"},{"t":"3. Nucleus細胞核","k":"li"},{"t":"• The largest organelle, it contains the deoxyribonucleic acid (DNA) / chromosomes of the cell for protein synthesis A thread-like structure","k":"li"},{"t":"• Surrounded by nuclear membranes composed of DNA and histone proteins, which","k":"li"},{"t":"around a fluid nucleoplasm, is the control condenses into visible chromosomes during cell division.","k":"p"},{"t":"center of the cell.","k":"p"},{"t":"synthesizing ribosomal RNA","k":"p"},{"t":"• Functions: (rRNA)","k":"li"},{"t":"• Direct the cell’s activities","k":"li"},{"t":"• Contains genetic information for protein synthesis","k":"li"},{"t":"4. Mitochondrion 粒線體","k":"li"},{"t":"• Mitochondria (plural)","k":"li"},{"t":"• No. of mitochondria in the cell depends on the cell’s energy needs","k":"li"},{"t":"• Typically round to oval in shape and range in size from 0.5 to 10 μm","k":"li"},{"t":"• Bound (包圍) by two membranes","k":"li"},{"t":"• Outer membrane → smooth","k":"li"},{"t":"• Inner membrane → deeply folded","k":"li"},{"t":"• Function: Release energy from food molecules and transform energy into ATP","k":"li"},{"t":"5. Endoplasmic Reticulum (ER) 內質網","k":"li"},{"t":"• A network of interconnected membrane throughout the cytoplasm","k":"li"},{"t":"• 2 types of ER:","k":"li"},{"t":"• Rough ER (RER)","k":"li"},{"t":"• Area of ER where ribosomes attached","k":"li"},{"t":"• Helps to synthesize proteins made by ribosomes","k":"li"},{"t":"• Smooth ER (SER)","k":"li"},{"t":"• Area of ER where NO ribosomes attached","k":"li"},{"t":"• Helps to synthesize and metabolize carbohydrates, lipids & other nonprotein materials","k":"li"},{"t":"FUNCTIONS OF CELL ORGANELLES","k":"h"},{"t":"Organelle / component Function Plasma (cell) membrane Controls materials in and out of cell Cytoplasm Serves as matrix substance for chemical reactions to occur Endoplasmic reticulum (ER) Rough ER: Assist protein synthesis Smooth ER: Metabolize nonpolar compound Ribosome Protein synthesis Golgi Complex Synthesize carbohydrate and pack molecules for secretion Mitochondrion Transform energy from food to ATP Lysosome Digest foreign molecules, and worn and damaged organelles Nucleus Contains genetic information and directs cellullar activity Nuclear membrane Control material in and out of the nucleus Nucleolus Produce ribosomal RNA for ribosomes","k":"p"},{"t":"Levels of Organization in the Body","k":"h"},{"t":"• Chemical","k":"li"},{"t":"• Atoms combined to form molecules","k":"li"},{"t":"• Cell","k":"li"},{"t":"• Cells are made of molecules","k":"li"},{"t":"• Tissue","k":"li"},{"t":"• Consists of similar types of cells","k":"li"},{"t":"• Organ","k":"li"},{"t":"• Made up of different types of tissues","k":"li"},{"t":"• (Organ) System","k":"li"},{"t":"• Consists of different organs that work closely together","k":"li"},{"t":"• Organism","k":"li"},{"t":"• Made up of the organ systems","k":"li"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.13] The Types of Tissue","k":"p"},{"t":"1. Muscle tissue - contracts to initiate movement in the body","k":"li"},{"t":"2. Nervous tissue - transmits and integrates information through the central and peripheral nervous systems","k":"li"},{"t":"3. Epithelial tissue - creates protective boundaries and is involved in the diffusion of ions and molecules","k":"li"},{"t":"4. Connective tissue - underlies and supports other tissue types","k":"li"},{"t":"1. Muscle Tissue肌肉組織 Skeletal muscle","k":"li"},{"t":"• For contraction","k":"li"},{"t":"• Types","k":"li"},{"t":"• Skeletal– attached to bones at both end by tendons","k":"li"},{"t":"• Cardiac- heart","k":"li"},{"t":"• Smooth– digestive tract, blood vessels, urinary and reproductive systems Cardiac muscle","k":"li"},{"t":"Smooth muscle","k":"h"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 4 p.146]","k":"p"},{"t":"2. Nervous Tissue 神經組織","k":"li"},{"t":"• Composed of neurons 神經元 (nerve cells) and supporting cells","k":"li"},{"t":"• Neuron: for generation and conduction of electrical events and neural signals","k":"li"},{"t":"• Supporting cells: support neurons","k":"li"},{"t":"3. Epithelial tissue 上皮組織","k":"li"},{"t":"• Two categories: epithelial membrane and glands","k":"li"},{"t":"• Epithelial membrane","k":"li"},{"t":"• One cell layer (simple membrane) or multiple layers (stratified membrane) which cover the body surfaces and line the cavity (lumen) of hollow organs","k":"li"},{"t":"• Three types based on their cell shape:","k":"li"},{"t":"• Squamous epithelium: a single layer of flat cells used for easy diffusion and filtration e.g. capillary walls, pulmonary alveoli, epidermis of skin","k":"li"},{"t":"• Cuboidal epithelium: a single layer of cube-shaped cells used for secretion and absorption e.g. lining of kidney tubules, ducts of exocrine glands","k":"li"},{"t":"• Columnar epithelium: a single layer of tall, thick cells often with microvilli used for absorption and secretion e.g. lining of digestive tract","k":"li"},{"t":"• Allow constant loss and renewal of cells","k":"li"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 4 p.123]","k":"p"},{"t":"4. Connective tissue 結締組織","k":"li"},{"t":"• Consists of connective tissue cells and large amount of extracellular material in the spaces between cells","k":"li"},{"t":"• Different types of connective tissue:","k":"li"},{"t":"• Connective tissue proper, contain matrix of collagen and tissue fluid","k":"li"},{"t":"• Loose connective tissue (or areolar tissue) e.g. dermis of skin","k":"li"},{"t":"• Dense connective tissue e.g. tendon, ligament","k":"li"},{"t":"• Supporting connective tissue:","k":"li"},{"t":"• Cartilage, contain matrix of collagen","k":"li"},{"t":"• Bone, contain matrix of collagen and calcium phosphate","k":"li"},{"t":"• Fluid Connective Tissue:","k":"li"},{"t":"• Blood, contain matrix of plasma","k":"li"},{"t":"• Adipose tissue, specialized connective tissue contains numerous fat globules [Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.138]","k":"li"},{"t":"Connective Tissue Organ Systems of the Body [Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.9]","k":"p"},{"t":"• Circulatory system • Immune system","k":"li"},{"t":"• Cardiovascular system • Sensory system","k":"li"},{"t":"• Lymphatic system","k":"li"},{"t":"• Nervous system","k":"li"},{"t":"• Respiratory system • Endocrine system","k":"li"},{"t":"• Digestive system • Reproductive system","k":"li"},{"t":"• Urinary system","k":"li"},{"t":"• Integumentary system","k":"li"},{"t":"• Musculoskeletal system","k":"li"},{"t":"• Muscular system","k":"li"},{"t":"• Skeletal system","k":"li"},{"t":"The human body is a complex system. The structures in the body work in concert to maintain homeostasis, a balance in the body’s internal environment.","k":"p"},{"t":"Gene（基因）","k":"h"},{"t":"Genes Chromosomes","k":"h"},{"t":"Gene • segments of DNA , estimated 20,000 genes in human.","k":"p"},{"t":"• long strings of DNA","k":"li"},{"t":"• wrapped around special proteins (histones)","k":"li"},{"t":"• instructions for genetic trait (e.g. • appear in pairs: 23 pairs of chromosomes, your hair color, eye color and body for a total of 46 chromosomes.","k":"li"},{"t":"• Genes are the functional units of heredity. height) and making proteins.","k":"li"},{"t":"• Heredity is the transmission of genetic traits from parent to offspring (such as height, eye color, and hair color).","k":"li"},{"t":"• Each gene is a segment of DNA (Deoxyribonucleic acid) that specifies the structure of an RNA (Ribonucleic acid) molecule.","k":"li"},{"t":"• The RNA produced can be:","k":"li"},{"t":"• Functional on its own (e.g., tRNA, rRNA), or","k":"li"},{"t":"• Used to produce a protein (via mRNA).","k":"li"},{"t":"• The process of producing RNA and/or proteins from DNA is called gene expression.","k":"li"},{"t":"• Gene expression that leads to protein production involves two main steps:","k":"li"},{"t":"• Transcription: DNA → RNA (occurs in the nucleus)","k":"li"},{"t":"• Translation: RNA → Protein (occurs in the cytoplasm at ribosomes) Gross structure of DNA (Deoxyribonucleic Acid) & RNA (Ribonucleic Acid)","k":"li"},{"t":"• For eukaryotic cells, DNA usually found in nucleus while RNA found in BOTH in and out of the nucleus RNA","k":"li"},{"t":"• single stranded • For prokaryotic cells (no TRUE nucleus), both DNA and RNA are nucleic acids as biomolecule","k":"li"},{"t":"• facilitate protein synthesis from DNA.","k":"li"},{"t":"• with Uracil, without Thymine.","k":"li"},{"t":"DNA","k":"h"},{"t":"• double helix form.","k":"li"},{"t":"• 2 strands (backbone) connected by hydrogen bonds.","k":"li"},{"t":"• long sequence of 4 nucleotides. (in pair of T - A and C – G)","k":"li"},{"t":"• contains genetic code to determine the function and development of an organism.","k":"li"},{"t":"DNA Protein Synthesis蛋白質合成","k":"h"},{"t":"• The process of cells to generate proteins using the information encoded in DNA (Deoxyribonucleic acid)","k":"li"},{"t":"• Both DNA and RNA are involved","k":"li"},{"t":"• Two main steps:","k":"li"},{"t":"1. Transcription occurs in the nucleus.","k":"li"},{"t":"2. Translation carried out in ribosomes Protein synthesis (continue) https://www.youtube.com/watch?v=gG7uCskUOrA","k":"li"},{"t":"Transcription","k":"h"},{"t":"• DNA is used as a template to make a messenger RNA molecule (mRNA).","k":"li"},{"t":"• The mRNA thus formed","k":"li"},{"t":"• exits the nucleus through a nuclear pore","k":"li"},{"t":"• travels to the ribosome for the next step, translation.","k":"li"},{"t":"Translation","k":"h"},{"t":"• genetic code in mRNA is read to make the amino acids,","k":"li"},{"t":"• which are linked together in a particular order based on the genetic code, forming protein.","k":"li"},{"t":"Protein Synthesis蛋白質合成","k":"h"},{"t":"• Transcription occurs in the nucleus. During this process, information stored in a segment of DNA is used to produce a complementary RNA molecule, called messenger RNA (mRNA).","k":"li"},{"t":"• The mRNA molecule moves to the ribosomes in the cytoplasm, where translation occurs. During this process, the nucleotide sequence of the mRNA is used to determine the composition of a polypeptide chain, a precursor to a protein.","k":"li"},{"t":"Overview of Gene Expression","k":"h"},{"t":"Gene expression occurs in two steps: transcription, which occurs in the nucleus, and translation, which occurs in the cytoplasm at ribosomes.","k":"p"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.108] Regulation of Gene Expression 基因表達調控 Regulation of gene expression by a hormone receptor","k":"p"},{"t":"• All body cells have the same DNA, but not all genes are active in every cell.","k":"li"},{"t":"• Transcription is regulated so that only necessary genes are expressed in each cell type.","k":"li"},{"t":"• Nuclear proteins associated with DNA help control which genes are transcribed.","k":"li"},{"t":"• During cell differentiation, some DNA segments become inactive, while others become more active.","k":"li"},{"t":"• e.g. Hemoglobin genes are active in developing red blood cells but inactive in most other cells.","k":"li"},{"t":"• Gene expression fluctuates in response to internal and external signals.","k":"li"},{"t":"• Regulatory molecules can increase or decrease transcription rates by interacting with nuclear proteins.","k":"li"},{"t":"• Example: Triiodothyronine (T3) hormone:","k":"li"},{"t":"• Enters cells (e.g., skeletal muscle cells).","k":"li"},{"t":"• Binds to nuclear proteins.","k":"li"},{"t":"• Increases transcription of specific genes.","k":"li"},{"t":"• Leads to more protein production, more mitochondria, and increased metabolism.","k":"li"},{"t":"DNA Replication Replication of DNA Replication during the S phase of interphase produces two identical","k":"p"},{"t":"(DNA複製) molecules of DNA.","k":"h"},{"t":"• During interphase, DNA appears as dispersed chromatin in the nucleus.","k":"li"},{"t":"• Replication begins when the two strands of each DNA molecule separate.","k":"li"},{"t":"• Each original strand serves as a template for a new complementary strand.","k":"li"},{"t":"• Complementary nucleotides pair with the nucleotides on each template strand.","k":"li"},{"t":"• The result is two identical DNA molecules.","k":"li"},{"t":"• Each new DNA molecule contains:","k":"li"},{"t":"• One original strand (from the parent DNA).","k":"li"},{"t":"• One newly synthesized strand.","k":"li"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.112]","k":"p"},{"t":"Cell Division 細胞分裂","k":"h"},{"t":"Cell Division ◼ All organisms require a continuous supply of new cells due to tear and wear: ➢ For growth ➢ For development ➢ For repair or replace ➢ For reproduce繁殖 ◼ Cell must double its mass and content in growth phase, called “interphase” before cell division (means cell reproduction) ◼ Mitosis有絲分裂 ◼ Meiosis減數分裂 ◼ Chromosomes染色體 contain genetic materials in a cell ◼ DNA replicate複製(過程) and duplicate 複製(結果) during 4 stages: ➢ Prophase ➢ Metaphase ➢ Anaphase ➢ Telophase","k":"p"},{"t":"Cell Division Mitosis","k":"h"},{"t":"• replication and duplication forms genetically identical cells","k":"li"},{"t":"• almost all the body’s cells, including eyes, skin, hair, and muscle cell.","k":"li"},{"t":"• growth & repair Meiosis","k":"li"},{"t":"• replication and duplication forms genetically different cells","k":"li"},{"t":"• division of cell nucleus to form two daughter cells","k":"li"},{"t":"• produces cells that are genetically unique from the parent and contain only half DNA","k":"li"},{"t":"• reproduction","k":"li"},{"t":"https://medlineplus.gov/genetics/understanding/howgeneswork/cellsdivide/","k":"p"},{"t":"Cell Death Apoptosis細胞凋亡 – natural death process of cells","k":"p"},{"t":"• e.g. a few days of cell life in our digestive tract.","k":"li"},{"t":"• e.g. over 2 million RBCs are replaced every second.","k":"li"},{"t":"• e.g. nerve cells in the brain and spinal cord, that do not reproduce at all.","k":"li"},{"t":"Necrosis細胞壞死 – unnatural death of cells.","k":"p"},{"t":"• e.g. due to disease or injury Apoptosis","k":"li"},{"t":"• Apoptosis is a normal, regulated process of programmed cell death.","k":"li"},{"t":"• It helps control cell numbers in tissues during development and adulthood.","k":"li"},{"t":"• In fetal development胚胎發育, it removes extra tissue (e.g., cells between fingers and toes).","k":"li"},{"t":"• In adult tissues, it maintains a stable number of cells.","k":"li"},{"t":"• It also eliminates:","k":"li"},{"t":"• Damaged cells","k":"li"},{"t":"• Virus-infected cells","k":"li"},{"t":"• Potential cancer cells","k":"li"},{"t":"• Immune cells can trigger apoptosis in harmful cells.","k":"li"},{"t":"Mechanism of Apoptosis","k":"h"},{"t":"• Regulated by specific genes that code for apoptosis-related proteins.","k":"li"},{"t":"• Some proteins are released from mitochondria into the cytosol.","k":"li"},{"t":"• These proteins activate other proteins that execute apoptosis.","k":"li"},{"t":"• Key steps:","k":"li"},{"t":"• Chromatin condenses and fragments.","k":"li"},{"t":"• Nucleus fragments.","k":"li"},{"t":"• Cell dies and fragments.","k":"li"},{"t":"• Macrophages phagocytize (engulf and digest) the cell fragments.","k":"li"},{"t":"Reference","k":"h"},{"t":"Goodenough, J., & McGuire, B. (2017). Biology of humans: Concepts, applications and issues (6th ed.).","k":"p"},{"t":"Pearson.","k":"p"},{"t":"Martini, F., Nath, J. L., Bartholomew, E. F., Ober, W. C., & Ober, C. E. (2024). Fundamentals of anatomy and physiology (12th ed.). Pearson Education, Inc.","k":"p"},{"t":"Patton, K. T., Bell, F., Thompson, T., & Williamson, P. (2024). The human body in health & disease (8th ed.). Elsevier.","k":"p"},{"t":"Patton, K. T., Bell, F. B., & Thompson, T. (2022). Anatomy and physiology (11th ed.). Elsevier.","k":"p"},{"t":"Saladin, K. S., & Gan, C. A. (2020). Human anatomy (6th ed.). McGraw-Hill Education.","k":"p"},{"t":"VanPutte, C. L., Regan, J., & Russo, A. (2022). Seeley’s anatomy & physiology (13th edition.). New York, New York: McGraw-Hill Education.","k":"p"},{"t":"Welsh, C. J., Prentice-Craver, C., & Shier, D. (2021). Hole's essentials of human anatomy & physiology (14th ed.). McGraw-Hill Education.","k":"p"},{"t":"Thank You!","k":"p"}]},{"id":"L2","titleZh":"人體生理學導論 II","titleEn":"Introduction to Human Physiology II","blocks":[{"t":"Introduction to Human Physiology II","k":"h"},{"t":"Module Intended Learning Outcomes (MILOs): On completion of this lesson, students are expected to be able to:","k":"p"},{"t":"• Explain the structure and function of cells, tissues and organs of major body systems and physiological processes.","k":"li"},{"t":"Contents","k":"h"},{"t":"• Metabolism","k":"li"},{"t":"• Enzyme","k":"li"},{"t":"• Homeostasis","k":"li"},{"t":"• Membrane transport","k":"li"},{"t":"Learning outcomes: By the end of this lecture, students will be able to:","k":"h"},{"t":"• Describe the basic concept of metabolism and its role in energy production and use in the body.","k":"li"},{"t":"• Explain the function of enzymes in speeding up chemical reactions and their importance in metabolism.","k":"li"},{"t":"• Define homeostasis and describe how the body maintains a stable internal environment.","k":"li"},{"t":"• Identify and explain different types of membrane transport (e.g., diffusion, osmosis, active transport) and their role in cell function.","k":"li"},{"t":"Metabolism 新陳代謝 Metabolism","k":"h"},{"t":"• A set of chemical reactions that happen in the cells of a living organism to sustain life​","k":"li"},{"t":"• Allows an organism to:​","k":"li"},{"t":"• Grow and reproduce​","k":"li"},{"t":"• Maintain their structures​","k":"li"},{"t":"• Respond to their environments","k":"li"},{"t":"• Two Categories​ ATP Derived from Catabolic Reactions Drives Anabolic Reactions Energy released by catabolism is required to form ATP from ADP and","k":"li"},{"t":"• Catabolism分解代謝 phosphate (Pi). Energy and a phosphate are given off when ATP is converted back to ADP during anabolism.","k":"li"},{"t":"• Anabolism合成代謝","k":"li"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 4 p.983] Catabolism分解代謝","k":"p"},{"t":"• The breakdown of food components (such as carbohydrates, proteins and dietary fats) into their simpler forms, which can then be used to provide energy and the basic building blocks needed for growth and repair","k":"li"},{"t":"• Glycolysis糖解作用 - metabolic pathway of the breakdown of glucose for energy ​(glyco for sugar, lysis for breaking down)","k":"li"},{"t":"Glycolysis is a series of chemical reactions which involves the breaking down of glucose to a 3-carbon molecule called pyruvic acid (Pyruvate) and Glycolysis takes place in the cytoplasm of the cells with no oxygen being necessary for this process.","k":"p"},{"t":"Very little energy is produced or generated during glycolysis. A net formation of 2ATPs are produced from complete oxidation of one glucose molecule during glycolysis but when further oxidized in the mitochondria, more energy molecules are produced.","k":"p"},{"t":"Anabolism合成代謝","k":"h"},{"t":"• The part of metabolism in which our body is built or repaired. Anabolism requires energy that ultimately comes from our food. When we eat more than we need for daily anabolism, the excess nutrients are typically stored in our body as fat. Stage of Anabolism","k":"li"},{"t":"• Examples of anabolism","k":"li"},{"t":"• bone growth mineralization and muscle mass build- Stage 1 Production of precursors such as up. amino acids, monosaccharides and nucleotides.","k":"li"},{"t":"Stage 2 Energy (ATP) consumption to turn the precursors into reactive form.","k":"p"},{"t":"Stage 3 Assembly of these activated precursors into complex molecules such as proteins, polysaccharides, lipids and nucleic acids.","k":"p"},{"t":"Stages of anabolism – DNA synthesis as an example.","k":"p"},{"t":"Enzymes酵素 Enzymes酵素","k":"h"},{"t":"• Biological catalysts that ​","k":"li"},{"t":"• Increase the rate of chemical reactions​","k":"li"},{"t":"• Speed up metabolism","k":"li"},{"t":"• Remain unchanged at the end of the reaction​","k":"li"},{"t":"• NO change the nature of the reaction or its final result​","k":"li"},{"t":"• Proteins​","k":"li"},{"t":"• Their catalytic actions results from their complex structure​","k":"li"},{"t":"• Aid digestion: break down large food molecules like fats, proteins, and starches into smaller parts your body can use.","k":"li"},{"t":"• e.g. maltase, lactase, carbohydrase….","k":"li"},{"t":"• lower the activation energy of a reaction by increasing the energy level of the substrate How does enzymes work?","k":"li"},{"t":"Synthesis Digestion","k":"h"},{"t":"• Active site orients substrates in • Active site binds substrate and correct position for reaction puts stress on bonds that must be","k":"li"},{"t":"• Enzyme brings substrate closer broken, making it easier to together separate molecules How does enzymes work?","k":"li"},{"t":"• Active Site:","k":"li"},{"t":"• Location on an enzyme where the substrate attaches","k":"li"},{"t":"• Very specific for the substrate","k":"li"},{"t":"• Substrate:","k":"li"},{"t":"• The reactants反應物 in an enzyme-catalyzed reaction","k":"li"},{"t":"• Products:","k":"li"},{"t":"• The end result of the reaction","k":"li"},{"t":"Enzyme Activation Energy and Enzymes","k":"h"},{"t":"• Activation energy is required to initiate chemical reactions.","k":"li"},{"t":"• Without an enzyme, a chemical reaction can proceed, but it needs more energy input.","k":"li"},{"t":"• Enzymes lower the activation energy, making it easier for the reaction to proceed.","k":"li"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.52] The lock and key model","k":"p"},{"t":"• Enzyme action that explains how enzymes fit their substrate.","k":"li"},{"t":"• The active site of an enzyme is structured to fit a specifically shaped substrate.","k":"li"},{"t":"• Once the substrate binds to the active site, the enzyme will facilitate the reaction and release products of the reaction.","k":"li"},{"t":"https://www.medicalnewstoday.com/articles/319704#how-they-work It is where the reaction occurs!","k":"p"},{"t":"Factors affecting the rate of enzymatic reaction","k":"h"},{"t":"1. Temperature","k":"li"},{"t":"2. pH","k":"li"},{"t":"3. Enzyme concentration","k":"li"},{"t":"4. Substrate concentration","k":"li"},{"t":"5. Presence of any inhibitors or activators","k":"li"},{"t":"1. Temperature","k":"li"},{"t":"• Increase in temperature will increase the rate of enzyme-catalyzed reactions","k":"li"},{"t":"• When maximum rate is reached, further temperature increase will decrease the rate of reaction since enzyme loses its active conformation and is denatured","k":"li"},{"t":"2. pH","k":"li"},{"t":"• pH = the power of hydrogen","k":"li"},{"t":"• Hydrogen ions with positive charges","k":"li"},{"t":"• Higher the amount of hydrogen ions, the more acidic of the area ➢Lower or higher pH ???","k":"li"},{"t":"2. pH","k":"li"},{"t":"• Most enzymes are active only within a very narrow range of pH","k":"li"},{"t":"• pH optimum: the pH at which an enzyme functions optimally","k":"li"},{"t":"• At extremes of pH the enzyme loses its active conformation and is denatured","k":"li"},{"t":"• The pH optimum of an enzyme usually reflects the pH of body fluid in which the enzyme is found","k":"li"},{"t":"3. Enzyme Activation 酵素激活","k":"li"},{"t":"• Enzyme activation is the process that turns an inactive enzyme into an active one capable of speeding up metabolic reactions.","k":"li"},{"t":"• Some enzymes are produced as inactive form that are later activated within the cell","k":"li"},{"t":"• Example:","k":"li"},{"t":"• In the cells of the pancreas, many digestive enzymes are produced as zymogens (enzyme in an inactive form), which are activated after they are secreted into the intestine","k":"li"},{"t":"• Activation of zymogens in the intestinal lumen protects the pancreatic cells from self-digestion","k":"li"},{"t":"4. Substrate Concentration and Reversible Reactions","k":"li"},{"t":"• The rate of enzymatic reactions increases when either the substrate concentration or the enzyme concentration is increased","k":"li"},{"t":"• If the enzyme concentration remains constant, the rate of the reaction increases as the substrate concentration is raised, up to a maximum rate","k":"li"},{"t":"• When the rate of the reaction does not increase upon further addition of substrate, the enzyme is said to be saturated Cofactor輔因子","k":"li"},{"t":"• A non-protein molecule that supports a biochemical reaction","k":"li"},{"t":"• Take the form of metal ions (inorganic), organic substances or other molecules with beneficial characteristics not typically present in amino acids.","k":"li"},{"t":"• e.g. iron, Zinc","k":"li"},{"t":"• Increase the speed of reaction Coenzymes輔酶","k":"li"},{"t":"• Organic molecules that bind to enzymes and help them function","k":"li"},{"t":"• A type of cofactor, always organic","k":"li"},{"t":"• Can be easily removed","k":"li"},{"t":"• Act as carriers","k":"li"},{"t":"• e.g. Vitamins","k":"li"},{"t":"https://www.pharmaguideline.com/2022/01/coenzymes-structure-and-biochemical-functions.html Enzyme Inhibitor酶抑制劑","k":"p"},{"t":"1. Competitive inhibitor競爭性抑制劑","k":"li"},{"t":"• Molecules that are shaped (and charged) just like substrate","k":"li"},{"t":"• Attach to the active site","k":"li"},{"t":"• BLOCK the substrate","k":"li"},{"t":"• Therefore inhibit the reaction Enzyme Inhibitor","k":"li"},{"t":"2. Non-competitive inhibitor/ Allosteric Site 非競爭性抑制劑","k":"li"},{"t":"• Molecules that DO NOT attach to active site","k":"li"},{"t":"• But attach to enzyme ➢CHANGE the shape of active site","k":"li"},{"t":"• Substrate cannot bind to altered active site","k":"li"},{"t":"• Therefore inhibit the reaction Examples of enzymatic reactions Enzyme Primary Location Reaction (Substrate → Product) Biological Function Triglycerides (Fats) → Fatty acids Breaks down dietary lipids in the Lipases Small intestine, stomach & glycerol digestive tract.","k":"li"},{"t":"Saliva, pancreatic secretions Starches (polysaccharides) → Initiates carbohydrate breakdown in the Amylase in small intestine Maltose & short chain sugars mouth and small intestine.","k":"p"},{"t":"Small intestine (brush Hydrolyzes disaccharide maltose into Maltase Maltose → Glucose + Glucose border) absorbable glucose.","k":"p"},{"t":"Small intestine (secreted by Proteins & polypeptides → Cleaves proteins into smaller peptide Trypsin pancreas) Peptides & amino acids chains and amino acids.","k":"p"},{"t":"Small intestine (brush Digest milk sugar (lactose) into simple Lactase Lactose → Glucose + Galactose border) monosaccharides.","k":"p"},{"t":"Neuromuscular junctions, Acetylcholine → Acetate + Deactivates neurotransmitters to Acetylcholinesterase nerve synapses Choline terminate nerve signal transmission.","k":"p"},{"t":"Nucleus / cytoplasm (during Deoxyribonucleotides → DNA Catalyzes the synthesis of new DNA DNA Polymerase cell division) strand strands during replication and repair.","k":"p"},{"t":"Homeostasis 體內平衡 Fluctuation Around a Set Point","k":"p"},{"t":"Homeostasis e.g. body temperature is a variable maintained near an ideal value, or set point.","k":"p"},{"t":"• Automatic process that a living thing uses to keep its body steady on the inside while continuing to adjust to changing conditions outside of the body, or in its environment.","k":"li"},{"t":"• The body makes these changes in order to work the right way and survive","k":"li"},{"t":"• Involve three systems:","k":"li"},{"t":"1. Receptor/Sensor","k":"li"},{"t":"2. Control Center","k":"li"},{"t":"3. Effector效應器","k":"li"},{"t":"Dynamic Equilibrium: Conditions are not strictly constant; instead, they fluctuate within a tight, healthy physiological range around a target set point.","k":"p"},{"t":"1. Negative Feedback","k":"li"},{"t":"• The response of the system is opposite to the change that set it in motion","k":"li"},{"t":"• More common","k":"li"},{"t":"• Serves to reduce an excessive response and keep a variable within the normal range.","k":"li"},{"t":"• Negative feedback is the primary mechanism involved in maintaining homeostasis. It works to counteract changes away from a set point, helping to stabilize physiological processes.","k":"li"},{"t":"Feedback Loop Feedback loops maintain homeostasis. Receptors signal the control center that a variable has deviated outside its normal range. The control center regulates the action of the effectors, which produce a response that returns the variable to the set point. In negative feedback, the return to set point stops the response.","k":"p"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.20]","k":"p"},{"t":"1. Negative Feedback","k":"li"},{"t":"Negative Feedback Mechanism: Body Temperature (a) Negative feedback is one of the mechanisms by which homeostasis is maintained. Receptors","k":"p"},{"t":"Blood glucose homeostasis signal the control center, which regulates the action of the effectors. In the example, body temperature is too high, so sweating occurs. Negative feedback stops the sweating when the body temperature returns to normal.","k":"p"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 1 p.21]","k":"p"},{"t":"2. Positive Feedback","k":"li"},{"t":"• Serves to intensify a response until an endpoint is reached","k":"li"},{"t":"• Fast forward mechanisms cause changes in a physiological variable before they are actually needed Question?","k":"li"},{"t":"• Blood pressure When your blood pressure rises, your blood vessels can tell there's more resistance to blood flow. They tell the brain this is happening, and the brain communicates with the heart and blood vessels in response. This causes the heart rate to slow as the blood vessels open up more, allowing your blood pressure to return to normal. The opposite happens when you have low blood pressure.","k":"li"},{"t":"Positive Feedback vs Negative Feedback?","k":"p"},{"t":"Membrane transport 跨膜運輸 Membrane transport","k":"p"},{"t":"• Movement of substances into and out of the cell across the cell membrane / plasma membrane","k":"li"},{"t":"• Semi-permeable / selectively permeable","k":"li"},{"t":"• Forming a barrier between the intracellular fluid (inside the cell), and extracellular fluid (outside the cell).","k":"li"},{"t":"• The framework consists of the lipid bilayer, made up of phospholipid molecules.","k":"li"},{"t":"• Two basic methods of transport​","k":"li"},{"t":"• Passive transport​ - No energy is required​","k":"li"},{"t":"• Active transport​ - Cell must provide metabolic energy (ATP)​ Passive Membrane Transport","k":"li"},{"t":"1. Diffusion","k":"li"},{"t":"2. Facilitated Diffusion","k":"li"},{"t":"3. Osmosis","k":"li"},{"t":"1. Diffusion","k":"li"},{"t":"• Net movement is from high concentration to low concentration, or down a concentration gradient","k":"li"},{"t":"• Particles tend to distribute themselves evenly within a solution","k":"li"},{"t":"• Equilibrium is reached when no further net diffusion occurs.","k":"li"},{"t":"Diffusion across the plasma membrane https://teachmephysiology.com/biochemistry/molecules-and-signalling/diffusion/","k":"p"},{"t":"1. Diffusion Simple Diffusion簡單擴散","k":"li"},{"t":"• Nonpolar and lipid-soluble substances","k":"li"},{"t":"• Diffuse directly through the lipid bilayer https://www.sciencefacts.net/wp-content/uploads/2020/02/Simple-Diffusion.jpg","k":"li"},{"t":"• e.g. Diffusion in the alveoli (O2, CO2)","k":"li"},{"t":"Facilitated Diffusion促進性擴散","k":"h"},{"t":"• Water soluble diffuse through channel proteins (for ions)","k":"li"},{"t":"• e.g. Glucose, ions (Na⁺, K⁺, Ca²⁺), glucose, ethanol, amino acids","k":"li"},{"t":"channel proteins [Adapted from Seeley's Anatomy and Physiology (13 ed.), Chapter 1 p.82] th","k":"p"},{"t":"2. Facilitated diffusion","k":"li"},{"t":"• Molecules move from the region of higher concentration to the region of lower concentration assisted by protein carriers within the membrane","k":"li"},{"t":"• Passive movement of molecules","k":"li"},{"t":"• Allow ions and polar molecules to diffuse into the cell","k":"li"},{"t":"• e.g. uptake of glucose in intestinal cells","k":"li"},{"t":"Facilitated diffusion [Adapted from Biology (2024), Chapter 5 Figure 5.9]","k":"p"},{"t":"3. Osmosis 滲透作用","k":"li"},{"t":"• The net movement of water molecules from a less concentrated solution (the region of high water potential高水勢) to a more concentrated solution (the region of lower water potential 低水勢) through a selectively permeable membrane 半透膜","k":"li"},{"t":"• e.g. Cell membrane of animal cell is selectively permeable","k":"li"},{"t":"• The water potential of the fluid surrounding the cells needs to be controlled carefully","k":"li"},{"t":"Differentially permeable membrane","k":"h"},{"t":"LOW water potential HIGH water potential (high concentration of (low concentration of solute) solute)","k":"p"},{"t":"• Osmosis usually results in a volume change​ Net movement of water molecules","k":"li"},{"t":"3. Example of Osmosis","k":"li"},{"t":"• Re-absorption of water by the proximal and distal convoluted tubules of the nephron (Urinary system)","k":"li"},{"t":"• Removal of wastes in the kidneys: In the kidneys, osmosis helps remove waste from the blood. Urea and other wastes are eliminated from the blood in the glomerulus, and then more water is removed by osmosis in the tubules to produce dilute urine. Fresh water moves into the tubules by osmosis.","k":"li"},{"t":"• Production of urine: Osmosis plays a role in urine concentration in the kidneys. As glomerular filtrate passes through the loop of Henle, osmosis draws water out in the highly concentrated medulla, forming more concentrated urine.","k":"li"},{"t":"3. Example of Osmosis","k":"li"},{"t":"• Absorption of water by the alimentary canal 消化道 — stomach, small intestine and the colon (Digestive system)","k":"li"},{"t":"• Absorption of water in the small intestine: When food containing water passes from the small intestine into the bloodstream, osmosis occurs - water molecules move from the higher concentration in the intestinal contents through the intestinal walls and into the bloodstream, which has a lower water concentration.","k":"li"},{"t":"This image shows how a cell responds in solutions with different concentrations of Types of Osmosis solutes compared to the cell.","k":"p"},{"t":"• Endosmosis - when a substance is placed in a hypotonic solution (lower solute concentration outside the cell), the solvent molecules move inside the cell and the cell becomes rigid.","k":"li"},{"t":"• Exosmosis - when a substance is placed in a hypertonic solution (higher solute concentration outside the cell), the solvent molecules move out of the cell and the cell becomes flaccid.","k":"li"},{"t":"https://www.labxchange.org/library/pathway/lx-pathway:91dfe1df-cf5f4e3a-aa61-25686e04f6ff/items/lb:LabXchange:1c15140a:lx_image:1/55104 Osmotic pressure changes the shape of red blood cells in hypertonic, isotonic, and hypotonic solutions.","k":"p"},{"t":"Osmotic Pressure Osmotic pressure is the pressure required to stop water from diffusing through a membrane by osmosis.","k":"p"},{"t":"4. Active Transport 主動運輸","k":"li"},{"t":"• A process that involves the movement of molecules from a region of lower concentration to a region of higher concentration against a gradient or an obstacle with the use of external energy","k":"li"},{"t":"Main Types","k":"h"},{"t":"• Primary Active Transport: Uses ATP directly to pump molecules across the membrane.","k":"li"},{"t":"• Secondary Active Transport: Uses an electrochemical gradient stored from other pumped ions to move substances.","k":"li"},{"t":"• Vesicular Transport囊泡運輸","k":"li"},{"t":"• Endocytosis 胞吞作用","k":"li"},{"t":"• Exocytosis 胞吐作用 Primary Active Transport 主要主動運輸","k":"li"},{"t":"• Molecules are transported across the membrane by breaking down adenosine triphosphate (ATP), include ions such as Na+, K+, Mg2+, and Ca2+.","k":"li"},{"t":"• Ion pumps or ion channels facilitate the transport of these charged molecules throughout the body","k":"li"},{"t":"• Energy source: hydrolysis of ATP ATP + H₂O → ADP + Inorganic Phosphate (Pᵢ) + Energy","k":"li"},{"t":"Sodium-potassium pump Secondary Active Transport 次級主動運輸","k":"p"},{"t":"• Energy source: use of ion concentration (often Na) difference across membrane ​(energy created from Primary Active Transport)","k":"li"},{"t":"• Example: symport; antiport e.g., Sodium-Glucose Transporters in small intestine and kidneys","k":"li"},{"t":"- Transport glucose by utilizing the energy stored in Na+ gradients.","k":"li"},{"t":"https://www.khanacademy.org/science/ap-biology/cell-structure-and-function/facilitated-diffusion/a/active-transport Basis of Primary Active Transport Secondary Active Transport differentiation The transport of molecules against a The transport of two distinct molecules across a Definition concentration gradient through the use of energy membrane using energy in other forms than ATP generated by ATP Number of Two types of molecules are transported molecules A single molecule is transported simultaneously transported The concentration gradient of driving ion supplies Energy source Uses energy generated from ATP energy for the transport of the driving ion/molecule against its concentration gradient Number of substances May transport one or more substances Must transport more than one substance transported Types of Transmembrane proteins are specific to the ion Both antiporters and symporters are used in transmembrane transported through them secondary active transport proteins used Types of molecules Ions like sodium, potassium, and calcium are Ions like sodium act as the driving molecules transported transported across cell membrane Sodium potassium pump, calcium pump in Examples Glucose-sodium pump, sodium-potassium pump49 / 53 muscles Vesicular Transport 囊泡運輸 Endocytosis胞吞作用","k":"p"},{"t":"• cellular process where the cell membrane engulfs large particles or fluids, allowing them to enter the cell","k":"li"},{"t":"• Phagocytosis - engulf solid substance","k":"li"},{"t":"• e.g., White blood cell eat bacteria","k":"li"},{"t":"Exocytosis胞吐作用","k":"h"},{"t":"• the process by which substances are expelled from the cell. It involves the fusion of vesicles with the plasma membrane to release their contents outside the cell","k":"li"},{"t":"• Substances are too large to diffuse","k":"li"},{"t":"• e.g., neurons secrete neurotransmitters","k":"li"},{"t":"• Both endocytosis and exocytosis are active transport processes https://digfir-published.macmillanusa.com/life11e/life11e_ch06_25.html Factors Affecting Rate of Active Transport","k":"li"},{"t":"1. Concentration ◼ The greater the concentration difference, the more the energy needed (as greater concentration gradient should be overcome)","k":"li"},{"t":"2. Energy (ATP) availability ◼ The lack of energy decreases the rate of active transport Reference Goodenough, J., & McGuire, B. (2017). Biology of humans: Concepts, applications and issues (6th ed.). Pearson.","k":"li"},{"t":"Mader, S. S. (2024). Biology . New York, New York : McGraw-Hill.","k":"p"},{"t":"Martini, F., Nath, J. L., Bartholomew, E. F., Ober, W. C., & Ober, C. E. (2024).","k":"p"},{"t":"Fundamentals of anatomy and physiology (12th ed.). Pearson Education, Inc..","k":"p"},{"t":"Patton, K. T., Bell, F., Thompson, T., & Williamson, P. (2024). The human body in health & disease (8th ed.). Elsevier.","k":"p"},{"t":"Patton, K. T., Bell, F. B., & Thompson, T. (2022). Anatomy and physiology (11th ed.). Elsevier.","k":"p"},{"t":"Saladin, K. S., & Gan, C. A. (2020). Human anatomy (6th ed.). McGraw-Hill Education.","k":"p"},{"t":"VanPutte, C. L., Regan, J., & Russo, A. (2022). Seeley’s anatomy & physiology (13th edition.). New York, New York: McGraw-Hill Education.","k":"p"},{"t":"Welsh, C. J., Prentice-Craver, C., & Shier, D. (2021). Hole's essentials of human anatomy & physiology (14th ed.). McGraw-Hill Education.","k":"p"},{"t":"Thank You!","k":"p"}]},{"id":"L3","titleZh":"心血管系統","titleEn":"Cardiovascular System 心血管系統","blocks":[{"t":"Module Intended Learning Outcomes (MILOs):","k":"h"},{"t":"On completion of this lesson, students are expected to be able to:","k":"h"},{"t":"• Explain the structure and function of cells, tissues and organs of major body systems and physiological processes.","k":"li"},{"t":"• Describe the interrelations between different body systems","k":"li"},{"t":"Learning outcomes: By the end of this lecture, students will be able to:","k":"h"},{"t":"• Understand the basic structure and function of the heart","k":"li"},{"t":"• Describe the blood components and their functions in vascular system","k":"li"},{"t":"• Describe pulmonary and systemic circulation in correct pathways","k":"li"},{"t":"• Understand types of blood vessels and identify their differences at different areas","k":"li"},{"t":"• Describe basic concept of cardiac cycle","k":"li"},{"t":"• Describe the role of baroreceptors in detecting changes in blood pressure and initiating the reflex to maintain homeostasis.","k":"li"},{"t":"Structure and Function of the Heart Cardiovascular system 心血管系統","k":"p"},{"t":"1. The heart心臟 (muscular pumping device)","k":"li"},{"t":"• Pump the blood throughout the body","k":"li"},{"t":"2. A network of blood vessels血管 with blood血液","k":"li"},{"t":"• Closed system 肺循環 體循環","k":"li"},{"t":"• With circulation循環","k":"li"},{"t":"• Blood can pass to different parts of body continuously (non-stop) via arteries動脈, veins靜脈 and capillaries微血管","k":"li"},{"t":"Systemic and Pulmonary Circulation","k":"h"},{"t":"The circulatory system consists of the pulmonary and systemic circulations. The right side of the heart pumps","k":"p"},{"t":"blood through vessels to the lungs and back to the left side of the heart through the pulmonary circulation.","k":"p"},{"t":"The left side of the heart pumps blood through vessels to the tissues of the body and back to the right side of","k":"p"},{"t":"the heart through the systemic circulation. [Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 20 p.714]","k":"p"},{"t":"Functions of Cardiovascular system","k":"h"},{"t":"1. Transportation of metabolic substances (by red blood cells)","k":"li"},{"t":"• Oxygen and carbon dioxide","k":"li"},{"t":"• Nutrients","k":"li"},{"t":"• Waste products (metabolic wastes, excessive water, and ions)","k":"li"},{"t":"The circulatory system is composed of blood vessels that carry the blood to the tissues of the body, allowing for the exchange of substances, such as O2, nutrients, CO2, and","k":"p"},{"t":"waste products, necessary to maintain homeostasis. [Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 21 p.756]","k":"p"},{"t":"Functions of cardiovascular system","k":"h"},{"t":"2. Regulation","k":"li"},{"t":"• Hormones and heat (to regulate blood pressure) e.g. Adrenaline","k":"li"},{"t":"• In thermoregulation: (1) Vasoconstriction → Blood pressure OR ?","k":"li"},{"t":"(2) Vasodilation → Blood pressure OR ?","k":"p"},{"t":"Thermoregulation in Humans:","k":"h"},{"t":"Vasodilation widens blood vessels near the skin’s surface to release heat, while vasoconstriction Thermoregulation narrows them to retain warmth. These processes are controlled through feedback loops involving the hypothalamus, which acts as the body’s thermostat.","k":"p"},{"t":"Functions of cardiovascular system","k":"h"},{"t":"3. Protection","k":"li"},{"t":"• Clotting → protects against blood loss during tissue damage (by platelet)","k":"li"},{"t":"• Immune → protects against pathogens (by white blood cells)","k":"li"},{"t":"Blood Clot A blood clot consists of fibrin, which Types of White Blood Cells traps red blood cells, platelets, and fluid.","k":"p"},{"t":"(a) Neutrophil, (b) eosinophil, (c) basophil, (d) lymphocyte, (e) monocyte/macrophage.","k":"p"},{"t":"What is blood?","k":"p"},{"t":"• Amount of blood circulating within an individual depends on their size and weight","k":"li"},{"t":"• Average human adult has nearly 5 L of circulating blood volume","k":"li"},{"t":"• Consist of","k":"li"},{"t":"1. Plasma血漿 – 55%","k":"li"},{"t":"2. Blood cells血細胞 – 45%","k":"li"},{"t":"• Erythrocytes (RBC)","k":"li"},{"t":"• Leukocytes (WBC)","k":"li"},{"t":"• Platelets血小板 血塊黃層 Plasma血漿 Serum 血清 :","k":"li"},{"t":"• Plasma excludes fibrinogen and other clotting proteins","k":"li"},{"t":"• Water","k":"li"},{"t":"• Plasma proteins","k":"li"},{"t":"• Albumins, globulins, fibrinogen","k":"li"},{"t":"• Nutrients","k":"li"},{"t":"• Glucose, amino acids, lipid, cholesterol, vitamins","k":"li"},{"t":"• Metabolic wastes e.g. urea","k":"li"},{"t":"• Hormones","k":"li"},{"t":"• Ions 血塊黃層","k":"li"},{"t":"• Enzymes","k":"li"},{"t":"• Antibodies Composition of Blood Approximate values for the components of blood in a normal adult.","k":"li"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 19 p.684]","k":"p"},{"t":"Blood cells - Erythrocyte紅血球 Shape and dimensions of a red blood cell","k":"p"},{"t":"• Cells that contain haemoglobin (Hb) 血紅素","k":"li"},{"t":"• Oxygen-transporting protein that gives blood its red colour","k":"li"},{"t":"• Transport oxygen to tissues in exchange for carbon dioxide (Gas exchange)","k":"li"},{"t":"• Biconcave雙凹盤形狀 disk shape → surface area for gas exchange","k":"li"},{"t":"Hemoglobin (a) Hemoglobin consists of four subunits, each with a globin and a heme血基質.","k":"p"},{"t":"There are two alpha (α) globins 血球蛋白and two beta (β) globins. A heme is associated with each globin. (b) Each heme contains one iron atom (Fe) located at the center of the heme group. Oxygen binds to the heme on hemoglobin molecule.","k":"p"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 19 p.690]","k":"p"},{"t":"Blood cells - Leukocytes白血球","k":"h"},{"t":"• Protection: against infection","k":"li"},{"t":"Blood cells – Platelet 血小板","k":"h"},{"t":"• Smallest blood cells","k":"li"},{"t":"• Also called thrombocytes","k":"li"},{"t":"• Function in clotting → cluster together to stop bleeding（hemostasis）止血","k":"li"},{"t":"Overview of Blood Cells","k":"h"},{"t":"15 16 The Heart The Heart","k":"p"},{"t":"• Size of a fist, hollow, cone-shaped","k":"li"},{"t":"• Between the 2nd and 5th ribs; superior to the diaphragm, behind the sternum (inferior mediastinum縱隔)","k":"li"},{"t":"• Lies between the lungs; within the thoracic cavity:","k":"li"},{"t":"• Great blood vessels","k":"li"},{"t":"• Thymus, esophagus, trachea, thyroid, parathyroid","k":"li"},{"t":"• 1/3 to the right of the midsternal line and 2/3 to the left","k":"li"},{"t":"• Base: upper part of the heart, directed toward the right shoulder and lies beneath the 2nd rib","k":"li"},{"t":"• Apex: inferior and pointed tip of the heart; oriented toward the left hip, and rests at about the 5th intercostal space Function of the Heart","k":"li"},{"t":"• To receive deoxygenated blood and transport metabolic waste products from the body, sending them to the lungs for oxygenation.","k":"li"},{"t":"• To pump oxygenated blood, which contains oxygen, nutrients, hormones, and other vital substances, to the cells, tissues, and organs throughout the body.","k":"li"},{"t":"• To maintain the circulatory system and regulate blood pressure.","k":"li"},{"t":"Pericardium心包膜","k":"h"},{"t":"• The pericardium, also known as the pericardial sac, is a double-layered, closed sac that surrounds and protects the heart. It consists of:","k":"li"},{"t":"• Fibrous Pericardium纖維性心包膜","k":"li"},{"t":"• Tough outer layer made of fibrous connective tissue","k":"li"},{"t":"• Prevents overexpansion of the heart","k":"li"},{"t":"• Anchors the heart within the mediastinum","k":"li"},{"t":"• Connects to the great vessels (e.g., aorta) above and the diaphragm below","k":"li"},{"t":"• Serous Pericardium漿膜性心包膜","k":"li"},{"t":"• Inner layer made of simple squamous epithelium","k":"li"},{"t":"• Provides a smooth, friction-reducing surface around the heart","k":"li"},{"t":"Heart in the Pericardium","k":"h"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 20 p.716]","k":"p"},{"t":"Heart Layers Also known as the heart wall, the heart consists of three layers:","k":"h"},{"t":"1. Epicardium心外膜","k":"li"},{"t":"• This is the outer protective layer, made of fibrous and loose connective tissue.","k":"li"},{"t":"2. Myocardium心肌層","k":"li"},{"t":"• The middle layer, composed of specialized cardiac muscle tissue, is responsible for the heart's pumping action.","k":"li"},{"t":"3. Endocardium心內膜","k":"li"},{"t":"• This is a thin, smooth layer of endothelial cells that lines the heart's chambers.","k":"li"},{"t":"Vena cava = Vein Anatomy of the Heart Pulmonary = Lung (Upper body to right heart) (To whole body)","k":"p"},{"t":"Heart Chambers Upper Chambers (receive blood): Right atrium (RA) Left atrium (LA) Lower Chambers (pump blood): Right ventricle (RV) Left ventricle (LV)","k":"p"},{"t":"Lower body to right heart) Artery= Away from heart The Heart Valves心臟瓣膜 Vein= Toward the heart","k":"p"},{"t":"Atrioventricular valves (AV valves)","k":"h"},{"t":"Function:","k":"h"},{"t":"• To ensure the unidirectional flow of blood through the heart chambers and great arteries.","k":"li"},{"t":"• To prevent backflow of blood when a chamber or vessel contracts.","k":"li"},{"t":"Blood Circulation循環","k":"h"},{"t":"1. Pulmonary Circulation肺循環","k":"li"},{"t":"2. Systemic Circulation體循環","k":"li"},{"t":"3. Coronary Circulation冠狀循環","k":"li"},{"t":"4. Portal Circulation肝門循環","k":"li"},{"t":"To maintain enough oxygenation when the blood is transported from the lungs to the systemic circulation","k":"p"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 20 p.713]","k":"p"},{"t":"1. Pulmonary Circulation肺循環","k":"li"},{"t":"• Blood supply for gas exchange in LUNGS:","k":"li"},{"t":"• Carries deoxygenated blood from right heart to the lungs","k":"li"},{"t":"• Returns oxygenated blood from lungs to left heart","k":"li"},{"t":"Pulmonary Circulation","k":"h"},{"t":"Systemic Circulation","k":"h"},{"t":"25","k":"p"},{"t":"1. Pulmonary Circulation肺循環 Artery= Away from heart","k":"li"},{"t":"Vein= Toward the heart Pathway:","k":"h"},{"t":"1. Right atrium (Receiving chamber) → tricuspid valve → right ventricle (Discharging chamber)","k":"li"},{"t":"2. → pulmonary semilunar valve → pulmonary trunk → pulmonary arteries (left and right)","k":"li"},{"t":"3. → lungs (gas exchange)","k":"li"},{"t":"4. → pulmonary veins → left atrium (Receiving chamber) → mitral/bicuspid valve → left ventricle (Discharging chamber)","k":"li"},{"t":"*artery carries deoxygenated blood","k":"p"},{"t":"2. Systemic Circulation體循環","k":"li"},{"t":"• Carries oxygen and nutrients to all other parts of body and collect carbon dioxide and wastes from whole body","k":"li"},{"t":"• Carries oxygenated blood from left heart to the body","k":"li"},{"t":"• Returns deoxygenated blood from body to right heart","k":"li"},{"t":"Pulmonary Circulation","k":"h"},{"t":"Systemic Circulation","k":"h"},{"t":"27 Artery= Away from heart","k":"p"},{"t":"2. Systemic Circulation Vein= Toward the heart","k":"li"},{"t":"Pathway:","k":"h"},{"t":"1. Left ventricle (Discharging chamber)","k":"li"},{"t":"2. → aortic semilunar valves → aorta","k":"li"},{"t":"3. → whole body","k":"li"},{"t":"4. → Superior and inferior vena cava","k":"li"},{"t":"5. → right atrium (Receiving chamber)","k":"li"},{"t":"*vein carries oxygenated blood A diagram of the circulatory system Coronary Circulation 冠狀循環 coronary sulcus","k":"p"},{"t":"Provides cardiac muscle with reliable supplies of oxygen and nutrients:","k":"h"},{"t":"• Reference for the diagram: Lecture notes of Human Biology from the HD in Nursing programme. (n.d.)","k":"li"},{"t":"Arterial Supply","k":"h"},{"t":"• From the base of the aorta and encircle the heart in the coronary sulcus (groove between the atria and ventricles) Venous Supply","k":"li"},{"t":"• Several cardiac veins drain into the coronary sinus, then empty into the right atrium","k":"li"},{"t":"Any coronary disorder or disease can reduce the flow of oxygen and nutrients to the heart muscle ➢ Increase risk of heart attack and possibly death","k":"p"},{"t":"Cardiac Excitation (Cardiac Conduction System) 心臟傳導系統 A network of specialized cells (autorhythmic myocardium)","k":"p"},{"t":"• Self-excitable; repeatedly generate action potential that trigger heart contraction","k":"li"},{"t":"• They acts as a pacemaker. Setting the rhythm of electrical excitation; initiate each heartbeat (pacemaker)","k":"li"},{"t":"• Process of electrical activity related to contraction of heart by stimulates the contraction of contractile myocardium in a coordinated (sequential) manner","k":"li"},{"t":"• Involves electrical signals by SA node and cardiac muscles (from the atria to the ventricles) to control heartbeat","k":"li"},{"t":"• Ensuring efficient pumping of blood","k":"li"},{"t":"• Involves: ❖ Sinoatrial node (SA node) – initiates the heartbeat (pacemaker) ❖ Atrioventricular node (AV node) - delays the impulse slightly ❖ Bundle of His (Atrioventricular bundle), left and right bundle branches ❖ Purkinje fibers (throughout the ventricle)","k":"li"},{"t":"Cardiac Excitation","k":"h"},{"t":"1. Initiation of Action Potential:","k":"li"},{"t":"• The SA node generates an action potential (pacemaker) that spreads across the atrial walls.","k":"li"},{"t":"2. Atrial Contraction:","k":"li"},{"t":"• The action potential causes the atria to contract, pushing blood into the ventricles.","k":"li"},{"t":"3. Signal Propagation to Ventricles:","k":"li"},{"t":"• The action potential travels from the AV node through the AV bundle (Bundle of (Bundle of His) His), bundle branches, and Purkinje fibers, stimulating the ventricular walls.","k":"li"},{"t":"4. Ventricular Contraction:","k":"li"},{"t":"• The ventricles contract, starting from the apex and moving upward toward the base of the heart, efficiently pumping blood out.","k":"li"},{"t":"Cardiac Excitation","k":"h"},{"t":"Both atria Both ventricles SA AV Bundle Purkinje → → depolarize & → → → depolarize & node node of His fibers contract contract","k":"p"},{"t":"Cardiac Cycle心動週期","k":"h"},{"t":"• A process of repetitive systole收縮期 (contraction; blood leaves the chamber) and diastole舒張期 (relaxation; blood fills the chamber) of heart chambers","k":"li"},{"t":"• One complete contraction and relaxation of all four chambers of the heart S1","k":"li"},{"t":"• Total duration is 0.8 seconds in a heart beating 74 bpm S2","k":"li"},{"t":"1. Atrial systole : 0.1 seconds","k":"li"},{"t":"2. Ventricular systole : 0.3 seconds","k":"li"},{"t":"3. Complete cardiac (4 chambers) diastole : 0.4 seconds Mechanical Events of Cardiac Cycle Systole收縮期 Isovolumetric ventricular contraction","k":"li"},{"t":"1. Ventricle contract","k":"li"},{"t":"2. Ventricle pressure > atrium pressure → AV valves closed. S1","k":"li"},{"t":"→ First heart sound S1 “Lup”","k":"p"},{"t":"3. Ventricle pressure < aorta and pulmonary artery pressure → Pulmonary and aortic valves closed.","k":"li"},{"t":"Ventricular ejection","k":"h"},{"t":"1. Ventricular pressure > aorta and pulmonary artery pressure → Aortic and pulmonary valves open.","k":"li"},{"t":"→ Blood is ejected from ventricles (stroke volume) Diastole舒張期 Isovolumetric ventricular relaxation","k":"p"},{"t":"1. Ventricle relax (end-systolic volume)","k":"li"},{"t":"2. Ventricle pressure < aorta and pulmonary artery pressure → aortic and pulmonary valves close.","k":"li"},{"t":"→ Second heart sound S2 “Dup”","k":"p"},{"t":"3. AV valves remain closed → No change in ventricular volume","k":"li"},{"t":"Ventricular Filling Phase S2 “Dup”","k":"p"},{"t":"1. Blood is filled into atrium","k":"li"},{"t":"2. Atrium pressure > ventricle pressure → AV valves open.","k":"li"},{"t":"→ Blood is filled into ventricle","k":"p"},{"t":"Atrial contraction → Blood is further filled into ventricle (enddiastolic volume)","k":"p"},{"t":"Heart Sound心音","k":"h"},{"t":"• The heart produces two main sounds, heard using a stethoscope: First heart sound S1 “Lub” ◦ Produced by closing of AV valves during isovolumetric ventricular contraction Second heart sound S2 “Dub” ◦ Produced by closing of aortic and pulmonary valves when the pressure in ventricles falls below the pressure in arteries Electrocardiography (ECG) 心電圖 Limb leads (I,II,III) Vertical plane","k":"li"},{"t":"• Also called electrocardiogram.","k":"li"},{"t":"Each (ECG) electrode captures the heart's electrical activity from its specific placement on the body's surface.","k":"p"},{"t":"Chest leads (V1–V6) Horizontal plane Electrocardiography (ECG) 心電圖","k":"p"},{"t":"• P wave = atrial depolarization","k":"li"},{"t":"• QRS complex = onset of ventricular depolarization","k":"li"},{"t":"• T wave = ventricular repolarization","k":"li"},{"t":"• Atrial repolarization record is masked by the larger QRS complex Electrocardiography (ECG) 心電圖 The Vascular System 血管系統 The circulatory system is composed of blood vessels that carry the blood to the tissues of the body, allowing for the exchange of substances, such as O2, nutrients, CO2, and waste products, necessary to maintain homeostasis.","k":"li"},{"t":"[Adapted from Seeley's Anatomy and Physiology (13th ed.), Chapter 21 p.756] The Vascular System血管系統: Blood Vessels血管","k":"p"},{"t":"• Transport blood to the tissues and back","k":"li"},{"t":"• Carry blood away from the heart","k":"li"},{"t":"• Arteries (Artery)","k":"li"},{"t":"• Arterioles","k":"li"},{"t":"• Exchanges between tissues and blood","k":"li"},{"t":"• Capillary beds","k":"li"},{"t":"• Return blood toward the heart","k":"li"},{"t":"• Venules","k":"li"},{"t":"• Veins Artery動脈 Direction of blood flow ➢ Away from heart to the body's tissues and organs.","k":"li"},{"t":"Presence of valves ➢ Absent (except at the base of pulmonary artery and aorta) Wall & thick layer of fibrous Lumen tissue thick muscular wall to withstand high pressure; more elastic small lumen","k":"p"},{"t":"Nature of blood ➢ Oxygenated blood (except in the pulmonary artery)","k":"p"},{"t":"Blood pressure ➢ High","k":"p"},{"t":"(http://www.nytimes.com/imagepages/2007/08/01/health/adam/18020Developmentalprocessofatherosclerosis.html) Artery Force for blood flow ➢ Pumping action of heart ➢ Periodic stretching of the wall of arteries is called a pulse","k":"p"},{"t":"Location ➢ Deeper inside body Capillaries微血管","k":"p"},{"t":"• Capillaries are the smallest blood vessels in the body.","k":"li"},{"t":"• Composed of a single layer of endothelial cells (one cell thick!!)","k":"li"},{"t":"• Capillary bed (a network of numerous capillaries) connecting arterioles and venules","k":"li"},{"t":"• The walls of capillaries are one cell thick and consist of endothelial cells, making them semipermeable.","k":"li"},{"t":"• Facilitate exchange of water, O2, CO2, nutrients and waste","k":"li"},{"t":"• Capillaries come in three structural types:","k":"li"},{"t":"• Continuous;","k":"li"},{"t":"• Fenestrated;","k":"li"},{"t":"• Sinusoids.","k":"li"},{"t":"Vein靜脈 Direction of blood flow ➢ Towards the heart from the body’s tissues and organs.","k":"p"},{"t":"Presence of valves ➢ Present. To prevent backflow of blood, ensuring it moves in one direction only.","k":"p"},{"t":"Wall & Lumen (內腔) thin layer of fibrous tissue","k":"p"},{"t":"thinner muscular wall; less elastic large lumen to reduce resistance of blood flow","k":"p"},{"t":"Nature of blood ➢ Deoxygenated blood (except in the pulmonary vein)","k":"p"},{"t":"Blood pressure ➢ Low (http://www.vascularconcepts.com/content/pages.php?pg=patients_cardio_system&page=the_blood) Vein Force for blood flow  Blood is forced  Valves are opened towards by blood pressure heart  Vein is squeezed by muscles","k":"p"},{"t":" Valves  Body muscles, are closed particularly those in to prevent the limbs, contract backflow of and press against the blood veins","k":"p"},{"t":"Location ➢ Close to the body surface","k":"p"},{"t":"(http://cnx.org/content/m46635/latest/2114_Skeletal_Muscle_Vein_Pump.jpg) Hemodynamics 血液動力學","k":"p"},{"t":"• Study of blood flow and the force involved in circulating blood throughout the cardiovascular system","k":"li"},{"t":"• Hemo = blood; Dynamics = power Key concepts:","k":"li"},{"t":"• Cardiac Output心輸出量","k":"li"},{"t":"• Blood Flow 血流","k":"li"},{"t":"• Influence by blood pressure, blood vessel diameter, blood viscosity and resistance within the vessels","k":"li"},{"t":"• Blood pressure血壓","k":"li"},{"t":"• Vascular Resistance血管阻力 (opposition to blood flow within the vessels)","k":"li"},{"t":"• Venous return 靜脈回流","k":"li"},{"t":"Cardiac Output (CO) 心輸出量","k":"h"},{"t":"• Volume of blood pumped by each •Stroke volume (SV) 心搏量 ventricle (left ventricle) per minute • volume of blood ejected from each ventricle at each heartbeat","k":"li"},{"t":"• Unit: L/min","k":"li"},{"t":"•End-diastolic volume (EDV) (Preload)","k":"li"},{"t":"• volume of blood in each ventricle at the end of diastole","k":"li"},{"t":"• Controlled by changing right before systole","k":"li"},{"t":"• Heart rate (HR): by stimulate/inhibit = volume of blood filled into each ventricle","k":"li"},{"t":"SA node","k":"h"},{"t":"•End-systolic volume (ESV) (Afterload)","k":"li"},{"t":"• Stroke volume (SV): by • volume of blood remained in each ventricle after ejection stimulate/inhibit ventricles CO = HR • SV SV = EDV – ESV","k":"li"},{"t":"e.g. If heart rate of 75 beat/min and e.g. If EDV = 135 mL, ESV = 65 mL eject 70 ml of blood with each beat: SV = 135 mL – 65 mL = 70 mL CO = 5250 ml/min (5.25 L/min) Stroke volume (SV) Frank-Starling Law of the Heart EDV= End Diastolic Volume (Preload)","k":"p"},{"t":"法蘭克-史達林定律","k":"h"},{"t":"• Increased EDV results in increased contractility and thus increased stroke volume.","k":"li"},{"t":"SV = EDV – ESV Factors Influencing Heart Rate CO = HR x SV","k":"p"},{"t":"• All three factors act on the sinoatrial (SA) node, which is the heart’s natural pacemaker:","k":"li"},{"t":"Increased Plasma Epinephrine","k":"h"},{"t":"• Epinephrine (adrenaline) is a hormone released during stress or physical activity.","k":"li"},{"t":"• It stimulates the SA node, leading to a faster heart rate.","k":"li"},{"t":"Increased Sympathetic Nerve Activity","k":"h"},{"t":"• The sympathetic nervous system activates the “fight or flight” response.","k":"li"},{"t":"• It increases both heart rate and force of contraction by stimulating the SA node.","k":"li"},{"t":"Decreased Parasympathetic Nerve Activity","k":"h"},{"t":"• The parasympathetic nervous system normally slows the heart rate.","k":"li"},{"t":"• Mediated by acetylcholine (opposes the SNS)","k":"li"},{"t":"• When its activity decreases, the inhibitory effect is reduced, resulting in a higher heart rate.","k":"li"},{"t":"Factors Influencing Stroke Volume CO = HR x SV","k":"p"},{"t":"Factor Effect on Heart","k":"h"},{"t":"End-Diastolic More blood fills the ventricles Ventricular before contraction → increases Volume(EDV) / stroke volume Pre-load","k":"p"},{"t":"Sympathetic Stimulates the heart → increases Nerve Activity heart rate and force of contraction","k":"p"},{"t":"Plasma Hormone (adrenaline) that Epinephrine enhances heart rate and contractility CO = HR x SV Regulation of HR, SV and CO EDV= End Diastolic Volume (Preload)","k":"p"},{"t":"Parasympathetic End-diastolic activity volume","k":"h"},{"t":"Sympathetic Sympathetic stimulate activity activity (Starling law)","k":"h"},{"t":"inhibit stimulate stimulate","k":"p"},{"t":"SA node ventricles","k":"h"},{"t":"Heart rate x Stroke volume","k":"h"},{"t":"Cardiac output","k":"h"},{"t":"Blood Pressure It is the force per unit area exerted against the inner wall of a blood vessel.","k":"p"},{"t":"= Arterial blood pressure","k":"p"},{"t":"• Elastic tube with large radius and low-resistance","k":"li"},{"t":"1. Systolic pressure","k":"li"},{"t":"• Maximum arterial pressure during ventricular ejection (about 125 mmHg)","k":"li"},{"t":"2. Diastolic pressure","k":"li"},{"t":"• Minimum arterial pressure before ventricular relaxation (about 75 mmHg)","k":"li"},{"t":"• Apparatus for measuring arterial blood pressure","k":"li"},{"t":"• Sphygmomanometer + stethoscope","k":"li"},{"t":"• Unit: millimeters of mercury (mmHg) CO = HR x SV","k":"li"},{"t":"Regulation of Arterial Pressure Mean arterial pressure (MAP) (average blood pressure during cardiac cycle) is determined by:","k":"p"},{"t":"• Cardiac output (CO)","k":"li"},{"t":"• Total peripheral resistance (TPR) (the sum of resistance to blood flow offered by all the systemic blood vessels)","k":"li"},{"t":"MAP (BP) = CO x TPR CO = HR x SV Regulation of arterial pressure MAP = CO x TPR","k":"p"},{"t":"Vasoconstriction or End-diastolic vasodilation of volume arterioles to large organ Sympathetic Parasympathetic activity activity Blood viscosity","k":"p"},{"t":"Stroke X Heart rate volume","k":"h"},{"t":"CO X TPR","k":"h"},{"t":"MAP Regulation of Arterial Pressure","k":"h"},{"t":"• The body uses several mechanisms to control blood pressure, ensuring it stays within a healthy range","k":"li"},{"t":"• Short Term Regulation:","k":"li"},{"t":"• Baroreceptor","k":"li"},{"t":"• Chemoreceptor","k":"li"},{"t":"• Hormones","k":"li"},{"t":"• Epinephrine and norepinephrine (CNS: sympathetic)","k":"li"},{"t":"• Long Term Regulation:","k":"li"},{"t":"• Hormones","k":"li"},{"t":"• Antidiuretic hormone (CNS: hypothalamus)","k":"li"},{"t":"• Atrial natriuretic peptide (heart)","k":"li"},{"t":"• Renin-angiotensin-aldosterone system (RAAS)","k":"li"},{"t":"• Liver, Kidneys, lungs, adrenal gland CO = HR x SV","k":"li"},{"t":"Baroreceptor Reflex MAP = CO x TPR","k":"p"},{"t":"• Homeostatically or steadily regulates arterial pressure responding to changes in pressure","k":"li"},{"t":"Arterial baroreceptors","k":"h"},{"t":"• Pressure receptors Carotid sinus and Aortic arch that detect pressure stretch of arterial wall","k":"li"},{"t":"• Constantly active, producing a baseline frequency of action potentials in the sensory neurons","k":"li"},{"t":"• Sudden blood pressure,  stretching of arterial wall,  stimulation on baroreceptors,  impulses (action potential frequency) sending to medullary cardiovascular/ cardioregulatory center in the medulla oblongata of brainstem (Parasympathetic activity ) Baroreceptor Reflex Increased BP Decreased BP CO = HR x SV Baroreceptor Reflex MAP = CO x TPR CO = HR x SV","k":"li"},{"t":"Chemoreceptors MAP = CO x TPR","k":"p"},{"t":"• Blood pressure is regulated by chemoreceptor reflexes that sensitive to oxygen and carbon dioxide","k":"li"},{"t":"• Prominent chemoreceptors are in carotid and aortic bodies","k":"li"},{"t":"• Send signals to vasomotor center of the medulla oblongata → vasoconstriction","k":"li"},{"t":"The cardiovascular centre (CVC) CO = HR x SV Renal Regulation (Kidney) MAP = CO x TPR","k":"p"},{"t":"• Kidney maintains long-term blood pressure by regulating blood volume (under the stimulation of Antidiuretic Hormone (ADH), or via renin production)","k":"li"},{"t":"• Increased blood pressure stimulates the kidneys to eliminate water thus reducing blood pressure","k":"li"},{"t":"• Decreased blood pressure stimulates the kidneys to do water retention, thus increasing blood pressure CO = HR x SV Renin-Angiotensin-Aldosterone System MAP = CO x TPR References Goodenough, J., & McGuire, B. (2017). Biology of humans: Concepts, applications and issues (6th ed.). Pearson.","k":"li"},{"t":"Mader, S. S. (2024). Biology . New York, New York : McGraw-Hill,.","k":"p"},{"t":"Martini, F., Nath, J. L., Bartholomew, E. F., Ober, W. C., & Ober, C. E. (2024).","k":"p"},{"t":"Fundamentals of anatomy and physiology (12th ed.). Pearson Education, Inc..","k":"p"},{"t":"Patton, K. T., Bell, F., Thompson, T., & Williamson, P. (2024). The human body in health & disease (8th ed.). Elsevier.","k":"p"},{"t":"Patton, K. T., Bell, F. B., & Thompson, T. (2022). Anatomy and physiology (11th ed.).","k":"p"},{"t":"Elsevier.","k":"p"},{"t":"Saladin, K. S., & Gan, C. A. (2020). Human anatomy (6th ed.). McGraw-Hill Education.","k":"p"},{"t":"VanPutte, C. L., Regan, J., & Russo, A. (2022). Seeley’s anatomy & physiology (13th edition.). New York, New York: McGraw-Hill Education.","k":"p"},{"t":"Welsh, C. J., Prentice-Craver, C., & Shier, D. (2021). Hole's essentials of human anatomy & physiology (14th ed.). McGraw-Hill Education.","k":"p"},{"t":"Thank You!","k":"p"}]}];
